import numpy as np
from PIL import Image
a = np.array(Image.open('first_frame.png')).astype(int)
def slice_row(y, x0=80, x1=165):
    print(f\"--- y={y}\")
    row=a[y]
    # print runs of quantized colors
    def q(px):
        r,g,b=px
        return (r//32*32, g//32*32, b//32*32)
    prev=None; start=x0
    for x in range(x0,x1):
        c=q(row[x])
        if c"'!=prev:
            if prev is not None:
                print(f"  x {start:3d}-{x-1:3d}: rgb~{prev}")
            prev=c; start=x
    print(f"  x {start:3d}-{x1-1:3d}: rgb~{prev}")
for y in (4,10,18,30,44,50,56,62,70,84,96,110,120,132):
    slice_row(y)
EOF'
